  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Creasta Cocoșului (Pasul Gutâi)', 'Zubatý sopečný hřeben Kohoutí hřebínek se tyčí přímo nad průsmykem Gutâi (987 m) na staré silnici DN18. Serpentiny s výhledy na obě strany jsou nejhezčím úsekem cesty mezi Baia Mare a Sighetem. U silnice stojí kultovní hospůdka Hanul lui Pintea spojená s legendárním zbojníkem Pintea Viteazul.', 47.7092, 23.7803, 'https://commons.wikimedia.org/wiki/Special:FilePath/Creasta%20Cocosului%202011.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Creasta%20Cocosului%202011.jpg"}'::text[], 0),
    (v_route, 'Veselý hřbitov v Săpânțě', 'Světový unikát: stovky modrých vyřezávaných křížů s naivními malbami a veršovanými, často velmi vtipnými epitafy o životě zesnulých. Dílo řezbáře Stana Ioana Pătrașe z 30. let dnes patří na seznam UNESCO. Přijeďte dopoledne, než dorazí autobusy; parkování pro motorky přímo u vstupu.', 47.9686, 23.6941, 'https://commons.wikimedia.org/wiki/Special:FilePath/Merry%20Cemetery,%20Sapanta,%20Maramures,%20Romania.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Merry%20Cemetery,%20Sapanta,%20Maramures,%20Romania.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Merry%20Cemetery%20-%20Sapanta%20-%20Romania%2002.jpg"}'::text[], 1),
    (v_route, 'Restaurace: Casa Iurca de Călinești (Sighetu Marmației)', 'Vyhlášená rodinná restaurace v historickém šlechtickém domě v centru Sighetu. Poctivá maramurešská kuchyně — sarmale, mămăligă s brynzou a domácí horincă. Ideální zastávka na oběd v půlce okruhu, dvůr je klidný a bezpečný i pro plně naložené motorky.', 47.9284, 23.8871, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sighetu%20Marmatiei%20Centrul%20istoric%20(2).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sighetu%20Marmatiei%20Centrul%20istoric%20(2).JPG"}'::text[], 2),
    (v_route, 'Klášter Bârsana', 'Rozlehlý dřevěný klášterní areál v údolí Izy, jehož kostelní věž patří k nejvyšším dřevěným stavbám Evropy. Všechno je vyřezáváno ručně z dubu a šindele, zahrady jsou udržované jako klenotnice. Krásná ukázka živé maramurešské tesařské tradice, vstup volný.', 47.7950, 24.0710, 'https://commons.wikimedia.org/wiki/Special:FilePath/Manastirea%20Barsana%20-%20Maramures.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Manastirea%20Barsana%20-%20Maramures.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Manastirea%20Barsana%20Maramures%20-%20vedere%20de%20ansamblu.jpg"}'::text[], 3),
    (v_route, 'Dřevěný kostel Budești Josani', 'Kostel sv. Mikuláše z roku 1643 zapsaný na seznamu UNESCO, se čtyřmi vížkami a vzácnými interiérovými malbami. Uvnitř je uložena drátěná košile zbojníka Pintey. Klidná vesnice bez turistického ruchu — zastávka na pár minut ticha.', 47.7286, 23.9522, 'https://commons.wikimedia.org/wiki/Special:FilePath/Biserica%20de%20lemn%20din%20Budesti%20Josani.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Biserica%20de%20lemn%20din%20Budesti%20Josani.JPG"}'::text[], 4),
    (v_route, 'Vesnice Breb', 'Nejfotogeničtější vesnice Maramureše: doškové stodoly, vyřezávané brány a výhled na Creasta Cocoșului. Vesnici si oblíbil i britský král Karel III., který tu koupil usedlost. Úzká asfaltka do vsi je místy hrbolatá — v klidu, stojí to za to.', 47.7461, 23.9089, 'https://commons.wikimedia.org/wiki/Special:FilePath/Breb%20village%20in%20Maramure%C5%9F%20County,%20Romania.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Breb%20village%20in%20Maramure%C5%9F%20County,%20Romania.jpg"}'::text[], 5);
  insert into public.routes
