  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Klášter Voroneț', 'Sixtinská kaple Východu — vnější freska Posledního soudu na západní stěně září unikátní voronețskou modří, jejíž receptura se dodnes nepodařilo rozluštit. Klášter založil Štěpán Veliký roku 1488 za pouhé tři měsíce. Parkoviště 200 m od brány, vstup pár lei.', 47.5172, 25.8636, 'https://commons.wikimedia.org/wiki/Special:FilePath/Biserica%20Voronet.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Biserica%20Voronet.JPG"}'::text[], 0),
    (v_route, 'Klášter Humor', 'Nejkomornější z malovaných klášterů, beze zdí a věží, zato s freskami v teplých červených tónech z roku 1535. Z dřevěné obranné věže za kostelem je pěkný výhled na celý areál. Bývá tu výrazně méně lidí než ve Voroneți.', 47.6070, 25.8433, 'https://commons.wikimedia.org/wiki/Special:FilePath/M%C4%83n%C4%83stirea%20Humor%20-%20vedere%20lateral%C4%83.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/M%C4%83n%C4%83stirea%20Humor%20-%20vedere%20lateral%C4%83.JPG"}'::text[], 1),
    (v_route, 'Klášter Moldovița', 'Opevněný klášter z roku 1532 s proslulou freskou Obléhání Konstantinopole na jižní stěně. Areál obklopený hradbami působí jako malá pevnost uprostřed květinových zahrad. Odtud začíná nejlepší motorkářský úsek trasy — stoupání na Ciumârnu.', 47.6850, 25.5709, 'https://commons.wikimedia.org/wiki/Special:FilePath/Moldovi%C8%9Ba%20Monastery%20(Romania).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Moldovi%C8%9Ba%20Monastery%20(Romania).jpg"}'::text[], 2),
    (v_route, 'Klášter Sucevița', 'Největší a nejmohutněji opevněný malovaný klášter se slavnou freskou Žebřík ctností na severní stěně. Zelené tóny frescek a bílé hradby s věžemi v rohu údolí tvoří jeden z nejkrásnějších obrazů Bukoviny. Sjíždí se k němu přímo z průsmyku Ciumârna.', 47.7781, 25.7099, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sucevi%C8%9Ba%20Monastery,%20Romania.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sucevi%C8%9Ba%20Monastery,%20Romania.jpg"}'::text[], 3),
    (v_route, 'Marginea – černá keramika', 'Vesnice proslulá jedinečnou černou keramikou vypalovanou bez přístupu vzduchu — technika stará přes 500 let. V hrnčířské dílně u hlavní silnice můžete sledovat práci na kruhu a koupit si misku, která se vejde do kufru. Milá krátká zastávka mezi kláštery.', 47.8092, 25.8225, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ceramica%20Marginea.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ceramica%20Marginea.jpg"}'::text[], 4),
    (v_route, 'Kostel Arbore', 'Nejstarší z malovaných kostelů (1502) a jediný, který nebyl klášterem — postavil ho dvořan Luca Arbore jako rodovou nekropoli. Fresky v odstínech zelené jsou dílem mistra Dragoșe Comana. Leží kousek stranou hlavního okruhu na zpáteční cestě přes Solcu.', 47.7350, 25.9260, 'https://commons.wikimedia.org/wiki/Special:FilePath/Biserica%20Arbore.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Biserica%20Arbore.jpg"}'::text[], 5);
