  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Salina Turda', 'Solný důl s historií od středověku, proměněný v surrealistický podzemní zábavní park: ruské kolo, jezírko s loďkami a amfiteátr 120 metrů pod zemí. Stálých 11 °C — vezměte si vrstvu navíc. Počítejte s hodinou a půl na prohlídku, motorku nechte na hlídaném parkovišti u vstupu Salina Durgău.', 46.5877, 23.7875, 'https://commons.wikimedia.org/wiki/Special:FilePath/Salina%20Turda%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Salina%20Turda%201.jpg"}'::text[], 0),
    (v_route, 'Soutěska Cheile Turzii', 'Skoro tři sta metrů vysoké vápencové stěny nad potokem Hășdate, ráj horolezců a jedna z přírodních ikon Transylvánie. Od parkoviště vede kaňonem pohodová stezka — na protažení nohou stačí půlhodina k prvním mostkům. Výhled na soutěsku je krásný už z příjezdové silnice od Petreștii de Jos.', 46.5628, 23.6810, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cheile%20Turzii%20(Turda%20Gorges).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cheile%20Turzii%20(Turda%20Gorges).jpg"}'::text[], 1),
    (v_route, 'Rimetea a Piatra Secuiului', 'Bělostná vesnice s maďarskou historií, kde nad náměstím s kostelem trůní vápencový monolit Piatra Secuiului (Székelykő, 1129 m). Díky orientaci údolí tu slunce vychází dvakrát — schová se za skálu a znovu se vyhoupne. Jedno z nejmalebnějších míst v celém Sedmihradsku, ideální na kávu na návsi.', 46.4550, 23.5680, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rimetea.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rimetea.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Piatra%20Secuiului%20seen%20from%20west.JPG"}'::text[], 2),
    (v_route, 'Ledová jeskyně Scărișoara', 'Podzemní ledovec o objemu přes 75 000 kubíků, starý zhruba 10 500 let — jeden z největších jeskynních ledovců Evropy. Sestup po schodech do 50 m hluboké vstupní šachty vyžaduje pevné boty a teplou vrstvu, uvnitř je kolem nuly. Od parkoviště v osadě Ghețar je to pěšky asi 10 minut.', 46.4879, 22.8087, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pestera%20Scarisoara%20-%20Sala%20Biserica.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pestera%20Scarisoara%20-%20Sala%20Biserica.jpg"}'::text[], 3),
    (v_route, 'Roșia Montană – římské zlaté doly', 'Nejstarší doložené hornické město Rumunska (Alburnus Maior, r. 131) a od roku 2021 památka UNESCO. V podzemí se dochovaly kilometry ručně tesaných římských štol, nahoře historické náměstí těžařských domů. Prohlídka štol s průvodcem trvá asi hodinu.', 46.3061, 23.1319, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rosia%20Montana%20Roman%20Gold%20Mines%202011%20-%20Galleries.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rosia%20Montana%20Roman%20Gold%20Mines%202011%20-%20Galleries.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Sarea''n Bucate (Turda)', 'Výborně hodnocená restaurace přímo u areálu solného dolu, jejíž název je slovní hříčkou se solí. Moderní rumunská kuchyně z lokálních surovin, poctivé polévky a domácí limonády — ideální tečka za okruhem. V sezóně je lepší rezervace.', 46.5867, 23.7838, 'https://commons.wikimedia.org/wiki/Special:FilePath/Salina%20Turda%205.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Salina%20Turda%205.jpg"}'::text[], 5);
