  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Přehrada Văliug', 'Horská nádrž na řece Bârzavě obklopená semenickými lesy, oblíbené letovisko obyvatel Reșițy. Silnice podél břehu nabízí pěkné výhledy a několik teras na kávu u vody. Odtud se dá odbočit i na horskou cestu Transsemenic.', 45.2422, 22.0155, 'https://commons.wikimedia.org/wiki/Special:FilePath/RO%20CS%20Lacul%20de%20acumulare%20Valiug%20(3).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/RO%20CS%20Lacul%20de%20acumulare%20Valiug%20(3).JPG"}'::text[], 0),
    (v_route, 'Vodopád Bigăr', 'Ikona rumunských kalendářů: krasový pramen padá přes osm metrů vysoký mechem obrostlý převis přímo u silnice DN57B, přesně na 45. rovnoběžce. Hlavní kaskáda se v roce 2021 částečně utrhla, místo ale zůstává kouzelné a zastávka zabere jen chvíli. Parkoviště hned u silnice.', 44.9247, 21.9536, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cascada%20Big%C4%83r.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cascada%20Big%C4%83r.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Izvorul%20Big%C4%83r.JPG"}'::text[], 1),
    (v_route, 'Vodopády Beușnița (Cheile Nerei)', 'Kaskády potoka Beu v národním parku Cheile Nerei-Beușnița, kde voda přepadá přes travertinové stupně v několika bílých závojích. Od parkoviště u Ochiul Beiului je to nenáročná procházka bukovým lesem. Nejvodnatější jsou na jaře po tání.', 44.9075, 21.8858, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cascadele%20Beu%C8%99ni%C8%9Bei.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cascadele%20Beu%C8%99ni%C8%9Bei.JPG"}'::text[], 2),
    (v_route, 'Jezírko Ochiul Beiului', 'Smaragdově tyrkysové krasové oko hluboké 3,6 metru, které nikdy nezamrzá. Barva vody je nejintenzivnější kolem poledne, kdy do jezírka svítí slunce. Přístup po lesní cestě z údolí Beu — část se dá opatrně dojet, zbytek pěšky.', 44.9036, 21.8894, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lacul%20Ochiul%20Beiului.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lacul%20Ochiul%20Beiului.jpg"}'::text[], 3),
    (v_route, 'Divadlo Mihai Eminescu (Oravița)', 'Nejstarší kamenné divadlo Rumunska (1817), postavené podle vzoru vídeňského Burgtheatru — hrál tu i císař František I. hostem. Oravița byla také výchozím bodem nejstarší horské železnice v zemi do Aniny, banátského Semmeringu. Příjemná kávová zastávka před závěrečným úsekem do Reșițy.', 45.0339, 21.6903, 'https://commons.wikimedia.org/wiki/Special:FilePath/Teatrul%201.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Teatrul%201.JPG"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Drobeta – ruiny Trajánova mostu', 'U Drobety stál největší most antického světa — přes kilometr dlouhé dílo Apollodóra z Damašku, po němž římské legie roku 105 vtrhly do Dácie. Dodnes z něj na břehu trčí mohutné pilíře, hned vedle jsou ruiny římského kastra a lapidárium muzea Železných vrat. Symbolický start trasy po stopách Římanů.', 44.6244, 22.6683, 'https://commons.wikimedia.org/wiki/Special:FilePath/Turnu%20Severin%20Drobeta.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Turnu%20Severin%20Drobeta.jpg"}'::text[], 0),
    (v_route, 'Orșova – dunajský přístav', 'Městečko v zátoce na soutoku Cerny s Dunajem, celé přestavěné v 60. letech, kdy původní Orșovu zatopila přehrada. Promenáda s výhledem na kilometr širokou hladinu je ideální na první kávu; za pozornost stojí i moderní katolický kostel ve tvaru stanu. Odtud začíná nejhezčí úsek podél kotlů.', 44.7253, 22.3961, 'https://commons.wikimedia.org/wiki/Special:FilePath/Orsova,%20Romania%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Orsova,%20Romania%20-%20panoramio.jpg"}'::text[], 1),
    (v_route, 'Klášter Mraconia', 'Klášter přímo na hladině Dunaje v ústí zatopeného údolí Mraconia — původní svatyni pohltila přehrada, nová stavba z 90. let stojí na skalní terase u silnice. Jedno z nejfotografovanějších míst rumunského Podunají. Malé parkoviště bývá o víkendech plné, v týdnu je tu klid.', 44.6103, 22.2565, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mraconia%20Monastery.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mraconia%20Monastery.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Manastirea%20Mraconia%20,%20Parcul%20Portile%20de%20Fier.jpg"}'::text[], 2),
    (v_route, 'Velké kotle (Cazanele Mari)', 'Nejužší místo dolního Dunaje: mezi stěnami Ciucaru Mare a srbského Velikého Štrbce se řeka svírá do pouhých pár set metrů a proudí jako v kotli. Od Dubové vede na hranu Ciucaru Mare značená stezka s výhledem, který bere dech. Z přístaviště v zátoce vyplouvají lodičky přímo do soutěsky i k jeskyni Ponicova.', 44.6183, 22.2647, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cazanele%20Dun%C4%83rii.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cazanele%20Dun%C4%83rii.jpg"}'::text[], 3),
    (v_route, 'Băile Herculane', 'Nejstarší lázně Evropy — horké sirné prameny tu využívali už římští legionáři a Herkulovy lázně zbožňovala i císařovna Sissi. Habsburská lázeňská架 architektura kolem Herkulova náměstí chátrá s morbidním půvabem, ale termální voda teče dál. Údolí Cerny nad městem je bránou do národního parku Domogled.', 44.8794, 22.4128, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cazinoul,%20Baile%20Herculane.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cazinoul,%20Baile%20Herculane.JPG"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Tulcea – brána do delty Dunaje', 'Přístavní město, odkud vyplouvají lodě do všech tří ramen dunajské delty. Nábřeží s Monumentem nezávislosti na návrší Colnicul Hora nabízí výhled na řeku i střechy města. Před vyjížďkou stojí za to koupit si mapu delty — třeba se sem vrátíte na lodní výlet.', 45.1786, 28.8047, 'https://commons.wikimedia.org/wiki/Special:FilePath/Monumentul%20Independentei%20din%20Tulcea.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Monumentul%20Independentei%20din%20Tulcea.jpg"}'::text[], 0),
    (v_route, 'Munții Măcinului', 'Nejstarší pohoří Rumunska — žulové hřebeny hercynského stáří obroušené na oblé rulíky a věžičky, dnes národní park. Hřeben Pricopan nad vesnicí Greci připomíná středomořskou macchii a žijí tu želvy i supi mrchožraví na tahu. Krátký výšlap od silnice nabídne výhled až k Dunaji.', 45.1892, 28.2286, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mun%C8%9Bii%20M%C4%83cinului.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mun%C8%9Bii%20M%C4%83cinului.jpg"}'::text[], 1),
    (v_route, 'Mešita Gazi Ali Paši (Babadag)', 'Nejstarší mešita Rumunska (1610) s kamenným minaretem, památka na tři století osmanské Dobrudže. Babadag byl kdysi významným městem na cestě z Istanbulu k dunajským pevnostem. Rychlá kulturní zastávka s výbornou tureckou kávou v okolí.', 44.8931, 28.7128, 'https://commons.wikimedia.org/wiki/Special:FilePath/Geamia%20Ali-Gazi%20Pa%C8%99a%20din%20Babadag.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Geamia%20Ali-Gazi%20Pa%C8%99a%20din%20Babadag.jpg"}'::text[], 2),
    (v_route, 'Pevnost Enisala', 'Jediná středověká pevnost v Rumunsku postavená Janovany — na vápencovém ostrohu nad lagunou Razim hlídala obchodní cestu k Černému moři. Zřícenina s obnovenou vstupní branou nabízí kruhový výhled na laguny, rákosiny a vinice, při západu slunce naprosto magický. Krátká odbočka z hlavní silnice, vstup pár lei.', 44.8828, 28.8367, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cetatea%20Enisala.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cetatea%20Enisala.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cetatea%20Enisala%202.jpg"}'::text[], 3),
    (v_route, 'Antická Histria', 'Nejstarší město na území Rumunska — milétská kolonie založená kolem roku 657 př. n. l. na břehu laguny Sinoe. Rozlehlé vykopávky chrámů, bazilik a hradeb doplňuje moderní muzeum. Po sedmi stoletích řecko-římského života město pohřbily nánosy Dunaje; dnes je to tiché místo mezi vodou a stepí.', 44.5486, 28.7756, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cetatea%20Histria%20Constanta.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cetatea%20Histria%20Constanta.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Ivan Pescar (Tulcea)', 'Nejznámější rybí podnik v Tulcei přímo na nábřeží — moderní pojetí lipovanské rybářské kuchyně, vyhlášená rybí polévka storceag a čerstvé úlovky z delty. Perfektní večeře po okruhu; v sezóně rezervujte předem.', 45.1772, 28.8000, 'https://commons.wikimedia.org/wiki/Special:FilePath/Danube%20Delta%20Biosphere%20Authority%20Head%20Office,%20Tulcea..JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Danube%20Delta%20Biosphere%20Authority%20Head%20Office,%20Tulcea..JPG"}'::text[], 5);
