  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Sighișoara – hodinová věž', 'Jediná trvale obydlená středověká citadela Evropy a rodiště Vlada Țepeșe, předobrazu Drákuly. Vystoupejte na hodinovou věž s orlojem a barevnou glazovanou střechou — výhled na věže a uličky je nejlepší v celém Sedmihradsku. Motorku nechte pod hradbami, do citadely se jde pěšky po dlažbě.', 46.2197, 24.7925, 'https://commons.wikimedia.org/wiki/Special:FilePath/Turnul%20cu%20Ceas%20din%20Sighisoara%2005.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Turnul%20cu%20Ceas%20din%20Sighisoara%2005.jpg"}'::text[], 0),
    (v_route, 'Opevněný kostel Biertan', 'Nejmohutnější saský opevněný kostel, tři prstence hradeb na kopci uprostřed vesnice a památka UNESCO. Sakristie má proslulý zámek s devatenácti západkami, div středověkého zámečnictví. Z ochozů je krásný výhled na vinice, kterými sem přijíždíte.', 46.1353, 24.5136, 'https://commons.wikimedia.org/wiki/Special:FilePath/Biertan%20Biserica%20fortificata.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Biertan%20Biserica%20fortificata.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Biertan%20fortified%20church%20entrance.jpg"}'::text[], 1),
    (v_route, 'Mediaș', 'Saské královské město s křivou věží Turnul Trompeților, která se naklání skoro jako ta v Pise. Náměstí Regele Ferdinand lemují měšťanské domy s podloubími a pastelovými fasádami. Dobrá zastávka na kávu v půli západní smyčky okruhu.', 46.1647, 24.3486, 'https://commons.wikimedia.org/wiki/Special:FilePath/Piata%20Regele%20Ferdinand,%20Medias.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Piata%20Regele%20Ferdinand,%20Medias.jpg"}'::text[], 2),
    (v_route, 'Opevněný kostel Saschiz', 'Památka UNESCO s věží inspirovanou sighișoarskou hodinovou věží, přímo u hlavní silnice. Nad vesnicí se navíc krčí zřícenina selské pevnosti, kam se Sasové stahovali při nájezdech. Ve vsi ochutnejte místní specialitu — džem a šťávu z rebarbory.', 46.1939, 24.9628, 'https://commons.wikimedia.org/wiki/Special:FilePath/RO%20MS%20Fortified%20Church%20Saschiz,%20Mures%20County.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/RO%20MS%20Fortified%20Church%20Saschiz,%20Mures%20County.jpg"}'::text[], 3),
    (v_route, 'Viscri', 'Nejslavnější saská vesnice — bílý opevněný kostel UNESCO na kopci, modré štíty domů a jediná prašná náves, kde chodí husy středem. Dům číslo 63 patří králi Karlu III., který sem jezdí desítky let. Příjezdová silnice je úzká s výmoly; pomalu, ať si užijete i výhledy.', 46.0553, 25.0889, 'https://commons.wikimedia.org/wiki/Special:FilePath/Viscri%20fortified%20church%20in%20Brasov%20county,%20Romania.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Viscri%20fortified%20church%20in%20Brasov%20county,%20Romania.jpg"}'::text[], 4),
    (v_route, 'Pevnost Rupea', 'Mohutná spirála hradeb na čedičovém suku nad silnicí Sighișoara–Brašov, osídleném už v pravěku. Rekonstruovaná pevnost má tři nádvoří a věže s výhledem na celé Podhůří Perșan. Od parkoviště pod hradem je to nahoru pár minut pěšky.', 46.0392, 25.2192, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rupea%20Fortress,%20Romania.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rupea%20Fortress,%20Romania.jpg"}'::text[], 5),
    (v_route, 'Restaurace: Casa cu Cerb (Sighișoara)', 'Legendární Dům s jelenem na rohu citadelního náměstí, renesanční hostinec s freskou jelena na fasádě. Sedmihradská kuchyně s německými kořeny — jelení guláš, kysané zelí, místní vína. Po večeři si projděte hradby, večer patří citadela jen místním.', 46.2194, 24.7920, 'https://commons.wikimedia.org/wiki/Special:FilePath/Strada%20Turnului,%20Cetatea%20Sighisoara.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Strada%20Turnului,%20Cetatea%20Sighisoara.JPG"}'::text[], 6);
