    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Soutěska Bicaz (Cheile Bicazului)', 'Osm kilometrů silnice sevřené mezi kolmými vápencovými stěnami až 300 metrů vysokými — v úseku Gât Iadului (Hrdlo pekla) se skály nad vozovkou téměř dotýkají. Jedna z nejikoničtějších motorkářských fotek Rumunska vzniká právě tady. Zastavujte jen na vyznačených místech, v sezóně tu bývají stánky a hodně lidí.', 46.8103, 25.8236, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cheile%20Bicazului,%20(gorges%20de%20bicaz)%20(1).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cheile%20Bicazului,%20(gorges%20de%20bicaz)%20(1).jpg"}'::text[], 0),
    (v_route, 'Rudé jezero (Lacu Roșu)', 'Jezero vzniklé roku 1837 sesuvem, který zahradil údolí — z hladiny dodnes trčí pahýly zatopených smrků jako les duchů. Kolem jezera vede promenáda s výhledem na skalní věž Suhardul Mic. Ochutnejte pstruha z místních udíren, jezerní klasiku.', 46.7886, 25.7908, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lacul%20Ro%C8%99u%20-%20lac%20de%20baraj%20natural%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lacul%20Ro%C8%99u%20-%20lac%20de%20baraj%20natural%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lacu%20Rosu%20walkpath%202007.JPG"}'::text[], 1),
    (v_route, 'Masiv Ceahlău', 'Posvátná hora Moldavska s věží Toaca (1904 m), opředená legendami o dáckém bohu Zalmoxidovi. Z letoviska Durău vede na vrchol nejkratší značená cesta; i bez výstupu stojí serpentiny k Durău za odbočku kvůli výhledům. Za jasného rána se masiv zrcadlí v hladině přehrady.', 47.0364, 25.9367, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ceahlau%20Toaca.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ceahlau%20Toaca.JPG"}'::text[], 2),
    (v_route, 'Přehrada Izvorul Muntelui (Barajul Bicaz)', 'Betonová hráz z roku 1960, ve své době jedna z největších v Evropě, zadržuje 35 km dlouhé jezero mezi horami. Silnice po západním břehu patří k nejhezčím jezerním úsekům v zemi. U hráze je vyhlídka a v přístavišti Potoci půjčovna lodí.', 46.9531, 26.0894, 'https://commons.wikimedia.org/wiki/Special:FilePath/Baraj%20Bicaz%20vedere%20spre%20lacul%20Izvorul%20Muntelui.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Baraj%20Bicaz%20vedere%20spre%20lacul%20Izvorul%20Muntelui.jpg"}'::text[], 3),
    (v_route, 'Piatra Neamț', 'Podhorské město přezdívané perla Moldavska, s knížecím dvorem Štěpána Velikého a kamennou zvonicí z roku 1499 přímo v centru. Lanovka na kopec Cozla nabízí výhled na město sevřené zalesněnými vrchy. Dobré místo na večeři a přespání po okruhu.', 46.9275, 26.3708, 'https://commons.wikimedia.org/wiki/Special:FilePath/Piatra%20Neamt%20Turnul%20lui%20Stefan%20,.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Piatra%20Neamt%20Turnul%20lui%20Stefan%20,.jpg"}'::text[], 4);
