    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Černý kostel (Brašov)', 'Největší gotický kostel mezi Vídní a Istanbulem, začernalý požárem roku 1689, s unikátní sbírkou anatolských koberců a šestitunovým zvonem. Stojí hned vedle náměstí Piața Sfatului s podloubími a kavárnami. Projděte si i uličku Strada Sforii, jednu z nejužších v Evropě.', 45.6410, 25.5884, 'https://commons.wikimedia.org/wiki/Special:FilePath/Biserica%20Neagra%20(Black%20Church),%20Brasov,%20Romania,%20Oct.%202012.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Biserica%20Neagra%20(Black%20Church),%20Brasov,%20Romania,%20Oct.%202012.jpg"}'::text[], 0),
    (v_route, 'Zámek Peleș', 'Letní rezidence krále Karla I., dokončená 1914 — neorenesanční skvost se 160 pokoji, vyřezávanými interiéry a prvním elektrickým osvětlením v zemi. Mnozí ho řadí mezi nejkrásnější zámky Evropy. Od parkoviště v Sinaii se jde ke vstupu asi deset minut lesní alejí.', 45.3600, 25.5426, 'https://commons.wikimedia.org/wiki/Special:FilePath/Peles-Castle-Sinaia-Romania.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Peles-Castle-Sinaia-Romania.jpg"}'::text[], 1),
    (v_route, 'Klášter Sinaia', 'Klášter ze 17. století, podle něhož dostalo jméno celé město — zakladatel ho pojmenoval po hoře Sinaj. Starý kostelík s freskami a klidný rajský dvůr jsou příjemným kontrastem k ruchu kolem Peleșe, který je odsud pár minut pěšky. Vstup za symbolické vstupné.', 45.3553, 25.5481, 'https://commons.wikimedia.org/wiki/Special:FilePath/Manastirea%20Sinaia.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Manastirea%20Sinaia.JPG"}'::text[], 2),
    (v_route, 'Pevnost Râșnov', 'Selská pevnost ze 13. století na skále 150 metrů nad městem, kam se vešla celá vesnice i se zvířaty. Podle pověsti kopali obležení studnu ve skále třicet let. Nahoru vede silnička i lanovka; výhled na Bucegi a Piatra Craiului je velkolepý.', 45.5883, 25.4606, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cetatea%20Rasnov%20si%20orasul.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cetatea%20Rasnov%20si%20orasul.JPG"}'::text[], 3),
    (v_route, 'Hrad Bran', 'Nejslavnější hrad Rumunska na skále nad průsmykem mezi Valašskem a Sedmihradskem, marketingově spojený s Drákulou — Bram Stoker ho nikdy neviděl, atmosféře věžiček a tajných schodišť to ale neubírá. Uvnitř je muzeum královny Marie, která hrad milovala. Dorazte před desátou, než přijedou autobusy.', 45.5150, 25.3672, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bran%20Castle%20TB1.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bran%20Castle%20TB1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Castelul%20Bran.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Sergiana (Brašov)', 'Vyhlášený sklepní podnik pár kroků od Piața Sfatului — sedmihradská a saská kuchyně v cihlových klenbách, vlastní řeznictví a porce, po kterých se dobře spí. Vyzkoušejte polévku v chlebu a plăcintu. Večer bývá plno, rezervujte.', 45.6421, 25.5896, 'https://commons.wikimedia.org/wiki/Special:FilePath/Piata%20Sfatului%20Brasov%20Ro.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Piata%20Sfatului%20Brasov%20Ro.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Sibiu – Piața Mare', 'Velké náměstí bývalého Hermannstadtu lemují barokní paláce a domy, jejichž střešní vikýře vypadají jako přivřené oči — místní říkají, že vás Sibiu pořád pozoruje. Kousek odtud je Most lhářů a věž Turnul Sfatului s vyhlídkou. Jedno z nejhezčích historických center Rumunska.', 45.7969, 24.1519, 'https://commons.wikimedia.org/wiki/Special:FilePath/Piata%20Mare%20din%20Sibiu.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Piata%20Mare%20din%20Sibiu.jpg"}'::text[], 0),
    (v_route, 'Cisnădioara – románský kostelík', 'Na strmém kopci nad vesnicí stojí jeden z nejstarších románských kostelů Rumunska (kolem 1200) obehnaný hradbou. Mladíci prý směli k oltáři donést valoun jen tehdy, když ho vynesli na kopec — zásoba střeliva pro obránce. Výstup od parkoviště zabere deset minut a odmění výhledem na Cindrel.', 45.7083, 24.1236, 'https://commons.wikimedia.org/wiki/Special:FilePath/Biserica%20fortificat%C4%83%20din%20cisn%C4%83dioara.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Biserica%20fortificat%C4%83%20din%20cisn%C4%83dioara.jpg"}'::text[], 1),
    (v_route, 'Rășinari', 'Jedna z nejstarších a největších pasteveckých vesnic Mărginimie, rodiště filozofa Emila Ciorana a básníka Octaviana Gogy. Malované domy, kamenné uličky a kostel s freskami; ze Sibiu sem dřív jezdila i tramvaj lesem. Odtud začíná serpentinové stoupání na Păltiniș.', 45.7000, 24.0630, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rasinari%2003.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rasinari%2003.jpg"}'::text[], 2),
    (v_route, 'Păltiniș (1440 m)', 'Nejvýše položené horské letovisko Rumunska, založené roku 1894 sedmihradskými Sasy v smrkových lesích pohoří Cindrel. Dřevěné vily Hohe Rinne, čistý vzduch a v zimě lyžování; filozof Constantin Noica tu vedl svou proslulou horskou školu myšlení. Stoupání ze Rășinari je řidičská lahůdka s výhledy na kotlinu Sibiu.', 45.6636, 23.9260, 'https://commons.wikimedia.org/wiki/Special:FilePath/Paltinis.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Paltinis.jpg"}'::text[], 3),
    (v_route, 'Skanzen ASTRA', 'Největší muzeum v přírodě v Evropě: 96 hektarů dubového lesa Dumbrava s třemi stovkami mlýnů, salaší, lisoven a chalup ze všech koutů Rumunska, propojených jezerem a alejemi. Na obhlídku toho hlavního počítejte s dobrou hodinou. Velké parkoviště přímo u vstupu.', 45.7644, 24.1447, 'https://commons.wikimedia.org/wiki/Special:FilePath/ASTRA%20National%20Museum%20Complex%20,%20main%20entrance%20of%20the%20Open%20air%20museum,%20Sibiu.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/ASTRA%20National%20Museum%20Complex%20,%20main%20entrance%20of%20the%20Open%20air%20museum,%20Sibiu.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Crama Sibiul Vechi (Sibiu)', 'Nejstarší sklepní restaurace v Sibiu v bývalém vinném sklepě — obsluha v krojích, cimbál a poctivé sedmihradské klasiky jako bulz, sarmale a pastevecký guláš. Pár kroků od Piața Mare, ideální večeře po okruhu. Večer rezervujte, sklep je malý a oblíbený.', 45.7952, 24.1497, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sibiu,%20Turnul%20Sfatului.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sibiu,%20Turnul%20Sfatului.jpg"}'::text[], 5);
