-- ════════════════════════════════════════════════════════════════════
-- MotoGo24 — SEED doporučených tras — RUMUNSKO (10 tras, červenec 2026)
-- NEAPLIKOVÁNO na živou DB — přehled a spuštění je na adminovi.
-- Trasy: is_active=false (Skryto) + status='approved' → ve Velíně zkontroluj a Publikuj.
-- Idempotence: každá trasa se před vložením smaže dle (name, branch_id).
-- ════════════════════════════════════════════════════════════════════
alter table public.routes add column if not exists countries text[] not null default '{}'::text[];

do $$
declare
  v_branch uuid;
  v_route  uuid;
begin
  -- Domovská pobočka = nejbližší k Mezné (49.3464, 15.2119); fallback první.
  select id into v_branch from public.branches
    order by (power(coalesce(gps_lat,0)-49.3464,2) + power(coalesce(gps_lng,0)-15.2119,2)) asc
    limit 1;
  if v_branch is null then
    raise exception 'Nenalezena žádná pobočka v public.branches — nelze nasadit trasy.';
  end if;

  -- Maramureš – dřevěné kostely a Veselý hřbitov
  delete from public.routes where name = 'Maramureš – dřevěné kostely a Veselý hřbitov' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Maramureš – dřevěné kostely a Veselý hřbitov', 'Okruh nejseverovýchodnějším koutem Rumunska, kde se čas zastavil: dřevěné kostely UNESCO, vyřezávané brány a senoseče jako z 19. století. Z Baia Mare vystoupáte serpentinami přes průsmyk Gutâi pod skalní hřeben Creasta Cocoșului a sjedete do údolí Mary a Izy. Vrcholem je světově proslulý Veselý hřbitov v Săpânțě s malovanými náhrobky a štíhlá věž kláštera Bârsana. Silnice jsou vesměs v dobrém stavu, ale počítejte s koňskými povozy, drůbeží na vozovce a pomalejším tempem přes vesnice. Nejlépe od května do října; odpoledne bývají v horách bouřky.', 'loop', 200, 300, 'medium',
     '[{"lat": 47.6573, "lng": 23.5681, "label": "Start: Baia Mare"}, {"lat": 47.7092, "lng": 23.7803, "label": "Pasul Gutâi"}, {"lat": 47.9686, "lng": 23.6941, "label": "Săpânța"}, {"lat": 47.9284, "lng": 23.8871, "label": "Sighetu Marmației"}, {"lat": 47.7950, "lng": 24.0710, "label": "Bârsana"}, {"lat": 47.7286, "lng": 23.9522, "label": "Budești"}, {"lat": 47.6667, "lng": 23.8631, "label": "Cavnic"}, {"lat": 47.6573, "lng": 23.5681, "label": "Cíl: Baia Mare"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=47.6573,23.5681&destination=47.6573,23.5681&travelmode=driving&waypoints=47.7092,23.7803%7C47.9686,23.6941%7C47.9284,23.8871%7C47.7950,24.0710%7C47.7286,23.9522%7C47.6667,23.8631', 'https://commons.wikimedia.org/wiki/Special:FilePath/Merry%20Cemetery,%20Sapanta,%20Maramures,%20Romania.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Creasta%20Cocosului%202011.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Merry%20Cemetery,%20Sapanta,%20Maramures,%20Romania.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sighetu%20Marmatiei%20Centrul%20istoric%20(2).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Manastirea%20Barsana%20-%20Maramures.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Biserica%20de%20lemn%20din%20Budesti%20Josani.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Breb%20village%20in%20Maramure%C5%9F%20County,%20Romania.jpg"}'::text[], '{"Creasta Cocoșului (Pasul Gutâi)","Veselý hřbitov v Săpânțě","Restaurace: Casa Iurca de Călinești (Sighetu Marmației)","Klášter Bârsana","Dřevěný kostel Budești Josani","Vesnice Breb"}'::text[], '{"RO"}'::text[], false, 4910, 'approved');

  -- Bukovina – malované kláštery UNESCO
  delete from public.routes where name = 'Bukovina – malované kláštery UNESCO' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Bukovina – malované kláštery UNESCO', 'Pohodový okruh zvlněnou Bukovinou mezi pěti malovanými kláštery, jejichž vnější fresky z 16. století přežily půl tisíciletí dešťů a mrazů. Silnice DN17A přes průsmyk Ciumârna nabízí sled dokonale klopených zatáček lesem — motorkáři jí přezdívají bukovinská Transfăgărășan v kapesním vydání. Mezi klášery projíždíte vesnicemi s malovanými štíty a dílnami na černou keramiku v Marginee. Provoz je slabý, asfalt převážně výborný, převýšení mírné. Ideální jarní a podzimní trasa; fresky nejlépe vyniknou v ranním světle.', 'loop', 160, 240, 'easy',
     '[{"lat": 47.5539, "lng": 25.8896, "label": "Start: Gura Humorului"}, {"lat": 47.5172, "lng": 25.8636, "label": "Voroneț"}, {"lat": 47.6070, "lng": 25.8433, "label": "Mănăstirea Humorului"}, {"lat": 47.6850, "lng": 25.5709, "label": "Vatra Moldoviței"}, {"lat": 47.6544, "lng": 25.4750, "label": "Pasul Ciumârna (1100 m)"}, {"lat": 47.7781, "lng": 25.7099, "label": "Sucevița"}, {"lat": 47.8092, "lng": 25.8225, "label": "Marginea"}, {"lat": 47.5539, "lng": 25.8896, "label": "Cíl: Gura Humorului"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=47.5539,25.8896&destination=47.5539,25.8896&travelmode=driving&waypoints=47.5172,25.8636%7C47.6070,25.8433%7C47.6850,25.5709%7C47.6544,25.4750%7C47.7781,25.7099%7C47.8092,25.8225', 'https://commons.wikimedia.org/wiki/Special:FilePath/Biserica%20Voronet.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Biserica%20Voronet.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/M%C4%83n%C4%83stirea%20Humor%20-%20vedere%20lateral%C4%83.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Moldovi%C8%9Ba%20Monastery%20(Romania).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sucevi%C8%9Ba%20Monastery,%20Romania.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ceramica%20Marginea.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Biserica%20Arbore.jpg"}'::text[], '{"Klášter Voroneț","Klášter Humor","Klášter Moldovița","Klášter Sucevița","Marginea – černá keramika","Kostel Arbore"}'::text[], '{"RO"}'::text[], false, 4920, 'approved');

  -- Apuseni – Salina Turda, soutěsky a ledová jeskyně
  delete from public.routes where name = 'Apuseni – Salina Turda, soutěsky a ledová jeskyně' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Apuseni – Salina Turda, soutěsky a ledová jeskyně', 'Celodenní okruh Západními Rumunskými horami: podzemní katedrála solného dolu Turda, vápencové věže soutěsky Cheile Turzii a maďarská vesnice Rimetea pod monolitem Piatra Secuiului. Údolím řeky Arieș pak vystoupáte do srdce Apusenských hor k ledové jeskyni Scărișoara, kde i v létě drží tisíce let starý ledovec. Zpáteční cesta vede přes zlatokopecké městečko Roșia Montană s římskými štolami. Silnice v údolí Arieș je zábavná a zatáčkovitá, místy s horším povrchem — jeďte s rezervou. Nejlepší od června do září, v horách bývá chladno i v létě.', 'loop', 250, 390, 'medium',
     '[{"lat": 46.5733, "lng": 23.7855, "label": "Start: Turda"}, {"lat": 46.5628, "lng": 23.6810, "label": "Cheile Turzii"}, {"lat": 46.4550, "lng": 23.5680, "label": "Rimetea"}, {"lat": 46.3644, "lng": 23.0464, "label": "Câmpeni"}, {"lat": 46.4879, "lng": 22.8087, "label": "Ghețar (Scărișoara)"}, {"lat": 46.2733, "lng": 23.0622, "label": "Abrud"}, {"lat": 46.3061, "lng": 23.1319, "label": "Roșia Montană"}, {"lat": 46.5733, "lng": 23.7855, "label": "Cíl: Turda"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.5733,23.7855&destination=46.5733,23.7855&travelmode=driving&waypoints=46.5628,23.6810%7C46.4550,23.5680%7C46.3644,23.0464%7C46.4879,22.8087%7C46.2733,23.0622%7C46.3061,23.1319', 'https://commons.wikimedia.org/wiki/Special:FilePath/Salina%20Turda%201.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Salina%20Turda%201.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cheile%20Turzii%20(Turda%20Gorges).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rimetea.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Pestera%20Scarisoara%20-%20Sala%20Biserica.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rosia%20Montana%20Roman%20Gold%20Mines%202011%20-%20Galleries.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Salina%20Turda%205.jpg"}'::text[], '{"Salina Turda","Soutěska Cheile Turzii","Rimetea a Piatra Secuiului","Ledová jeskyně Scărișoara","Roșia Montană – římské zlaté doly","Restaurace: Sarea''n Bucate (Turda)"}'::text[], '{"RO"}'::text[], false, 4930, 'approved');

  -- Banát – vodopád Bigăr a soutěska Nery
  delete from public.routes where name = 'Banát – vodopád Bigăr a soutěska Nery' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Banát – vodopád Bigăr a soutěska Nery', 'Divoký jihozápad Rumunska, kraj českých krajanských vesnic a nejzelenějších hor Banátu. Z Reșițy vystoupáte k přehradám nad Văliugem, kolem semenických lesů sjedete do hornické Aniny a dál po DN57B k pohádkovému vodopádu Bigăr, kde voda stéká přes mechový převis. Národním parkem Cheile Nerei pokračujete k tyrkysovému jezírku Ochiul Beiului a do Oravițy s nejstarším divadlem v zemi. Silnice jsou úzké, zatáčkovité a místy záplatované — typický banátský mix, který si žádá pozornost, ale odmění samotou a přírodou. Nejlépe květen až říjen.', 'loop', 220, 330, 'medium',
     '[{"lat": 45.3009, "lng": 21.8892, "label": "Start: Reșița"}, {"lat": 45.2422, "lng": 22.0155, "label": "Văliug"}, {"lat": 45.0794, "lng": 21.8570, "label": "Anina"}, {"lat": 44.9247, "lng": 21.9536, "label": "Vodopád Bigăr"}, {"lat": 44.8850, "lng": 21.7083, "label": "Sasca Montană"}, {"lat": 45.0339, "lng": 21.6903, "label": "Oravița"}, {"lat": 45.3009, "lng": 21.8892, "label": "Cíl: Reșița"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.3009,21.8892&destination=45.3009,21.8892&travelmode=driving&waypoints=45.2422,22.0155%7C45.0794,21.8570%7C44.9247,21.9536%7C44.8850,21.7083%7C45.0339,21.6903', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cascada%20Big%C4%83r.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/RO%20CS%20Lacul%20de%20acumulare%20Valiug%20(3).JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Cascada%20Big%C4%83r.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Cascadele%20Beu%C8%99ni%C8%9Bei.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Lacul%20Ochiul%20Beiului.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Teatrul%201.JPG"}'::text[], '{"Přehrada Văliug","Vodopád Bigăr","Vodopády Beușnița (Cheile Nerei)","Jezírko Ochiul Beiului","Divadlo Mihai Eminescu (Oravița)"}'::text[], '{"RO"}'::text[], false, 4940, 'approved');

  -- Cazanele Dunării – rumunský břeh Železných vrat
  delete from public.routes where name = 'Cazanele Dunării – rumunský břeh Železných vrat' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Cazanele Dunării – rumunský břeh Železných vrat', 'Silnice DN57 podél rumunského břehu Dunaje patří k nejkrásnějším říčním vyjížďkám Evropy: veletok se mezi vápencovými stěnami Ciucaru Mare zužuje do dunajských kotlů Cazanele, kde se asfalt vine těsně nad hladinou. Trasa začíná u ruin Trajánova mostu v Drobetě a končí v秘lázních Băile Herculane hluboko v údolí Cerny. Cestou vás čeká klášter Mraconia nad vodou, vyhlídky na kotle a přístavní promenáda v Orșově. Zatáčky jsou rychlé a přehledné, provoz mírný, povrch výborný. Jarní a podzimní světlo nad řekou je odměna sama o sobě; v létě počítejte s vedrem.', 'poi', 135, 210, 'easy',
     '[{"lat": 44.6318, "lng": 22.6561, "label": "Start: Drobeta-Turnu Severin"}, {"lat": 44.7253, "lng": 22.3961, "label": "Orșova"}, {"lat": 44.6942, "lng": 22.3608, "label": "Eșelnița"}, {"lat": 44.6103, "lng": 22.2565, "label": "Mraconia"}, {"lat": 44.6183, "lng": 22.2647, "label": "Dubova"}, {"lat": 44.8794, "lng": 22.4128, "label": "Cíl: Băile Herculane"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=44.6318,22.6561&destination=44.8794,22.4128&travelmode=driving&waypoints=44.7253,22.3961%7C44.6942,22.3608%7C44.6103,22.2565%7C44.6183,22.2647', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cazanele%20Dun%C4%83rii.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Turnu%20Severin%20Drobeta.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Orsova,%20Romania%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mraconia%20Monastery.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Cazanele%20Dun%C4%83rii.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cazinoul,%20Baile%20Herculane.JPG"}'::text[], '{"Drobeta – ruiny Trajánova mostu","Orșova – dunajský přístav","Klášter Mraconia","Velké kotle (Cazanele Mari)","Băile Herculane"}'::text[], '{"RO"}'::text[], false, 4950, 'approved');

  -- Dobrudža – hory Măcin, Enisala a antická Histria
  delete from public.routes where name = 'Dobrudža – hory Măcin, Enisala a antická Histria' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Dobrudža – hory Măcin, Enisala a antická Histria', 'Okruh krajem mezi Dunajem a Černým mořem, na dohled od dunajské delty: nejstarší pohoří Rumunska Munții Măcinului se žulovými hřebeny jako z Provence, osmanský Babadag s nejstarší mešitou v zemi a středověká pevnost Enisala na kopci nad lagunou Razim. Tečkou je antická Histria, nejstarší řecké město na rumunském území. Silnice se vlní otevřenou stepní krajinou s minimem provozu — rychlé, přehledné oblouky a všudypřítomný vítr. Na jaře je Dobrudža zelená a plná ptáků z delty, v létě spálená do zlatova; vyhněte se poledním vedrům a hlídejte si benzín, pumpy jsou dál od sebe.', 'loop', 280, 360, 'easy',
     '[{"lat": 45.1786, "lng": 28.8047, "label": "Start: Tulcea"}, {"lat": 45.1892, "lng": 28.2286, "label": "Greci (Munții Măcinului)"}, {"lat": 45.0333, "lng": 28.4667, "label": "Horia"}, {"lat": 44.8931, "lng": 28.7128, "label": "Babadag"}, {"lat": 44.8828, "lng": 28.8367, "label": "Enisala"}, {"lat": 44.5486, "lng": 28.7756, "label": "Histria"}, {"lat": 45.1786, "lng": 28.8047, "label": "Cíl: Tulcea"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.1786,28.8047&destination=45.1786,28.8047&travelmode=driving&waypoints=45.1892,28.2286%7C45.0333,28.4667%7C44.8931,28.7128%7C44.8828,28.8367%7C44.5486,28.7756', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cetatea%20Enisala.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Monumentul%20Independentei%20din%20Tulcea.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mun%C8%9Bii%20M%C4%83cinului.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Geamia%20Ali-Gazi%20Pa%C8%99a%20din%20Babadag.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cetatea%20Enisala.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cetatea%20Histria%20Constanta.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Danube%20Delta%20Biosphere%20Authority%20Head%20Office,%20Tulcea..JPG"}'::text[], '{"Tulcea – brána do delty Dunaje","Munții Măcinului","Mešita Gazi Ali Paši (Babadag)","Pevnost Enisala","Antická Histria","Restaurace: Ivan Pescar (Tulcea)"}'::text[], '{"RO"}'::text[], false, 4960, 'approved');

  -- Saská Transylvánie – Sighișoara, Biertan a Viscri
  delete from public.routes where name = 'Saská Transylvánie – Sighișoara, Biertan a Viscri' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Saská Transylvánie – Sighișoara, Biertan a Viscri', 'Okruh krajinou sedmihradských Sasů: středověká Sighișoara s hodinovou věží, opevněné kostely UNESCO v Biertanu, Saschizu a Viscri a mohutná pevnost Rupea na čedičovém kopci. Mezi vesnicemi se silnice vlní pastvinami a dubovými háji, kde se od středověku mnoho nezměnilo — pastevci, ovce a čapí hnízda na komínech. Hlavní tahy mají dobrý asfalt, odbočka do Viscri je úzká a záplatovaná, tam zvolněte. Pozor na povozy a traktory za horizontem. Nejkrásnější v květnu a červnu, kdy kvetou louky, a v září ve zlatém světle.', 'loop', 195, 300, 'medium',
     '[{"lat": 46.2197, "lng": 24.7925, "label": "Start: Sighișoara"}, {"lat": 46.1353, "lng": 24.5136, "label": "Biertan"}, {"lat": 46.1647, "lng": 24.3486, "label": "Mediaș"}, {"lat": 46.2286, "lng": 24.5764, "label": "Dumbrăveni"}, {"lat": 46.1939, "lng": 24.9628, "label": "Saschiz"}, {"lat": 46.0553, "lng": 25.0889, "label": "Viscri"}, {"lat": 46.0392, "lng": 25.2192, "label": "Rupea"}, {"lat": 46.2197, "lng": 24.7925, "label": "Cíl: Sighișoara"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.2197,24.7925&destination=46.2197,24.7925&travelmode=driving&waypoints=46.1353,24.5136%7C46.1647,24.3486%7C46.2286,24.5764%7C46.1939,24.9628%7C46.0553,25.0889%7C46.0392,25.2192', 'https://commons.wikimedia.org/wiki/Special:FilePath/Turnul%20cu%20Ceas%20din%20Sighisoara%2005.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Turnul%20cu%20Ceas%20din%20Sighisoara%2005.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Biertan%20Biserica%20fortificata.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Piata%20Regele%20Ferdinand,%20Medias.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/RO%20MS%20Fortified%20Church%20Saschiz,%20Mures%20County.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Viscri%20fortified%20church%20in%20Brasov%20county,%20Romania.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rupea%20Fortress,%20Romania.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Strada%20Turnului,%20Cetatea%20Sighisoara.JPG"}'::text[], '{"Sighișoara – hodinová věž","Opevněný kostel Biertan","Mediaș","Opevněný kostel Saschiz","Viscri","Pevnost Rupea","Restaurace: Casa cu Cerb (Sighișoara)"}'::text[], '{"RO"}'::text[], false, 4970, 'approved');

  -- Soutěska Bicaz, Rudé jezero a Ceahlău
  delete from public.routes where name = 'Soutěska Bicaz, Rudé jezero a Ceahlău' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Soutěska Bicaz, Rudé jezero a Ceahlău', 'Okruh kolem posvátné hory Moldavska: silnice DN12C se v soutěsce Bicaz doslova zařezává pod třistametrové převisy — nejdramatičtější kilometry asfaltu v Karpatech. Nahoře čeká Rudé jezero s uschlými kmeny trčícími z hladiny a sjezd do sikulského Gheorgheni. Zpět se vracíte údolím Bistrițy kolem přehrady Izvorul Muntelui, rumunského moře mezi horami, s výhledy na štíty Ceahlău. V soutěsce pozor na mokré pásy pod skalami, padající kamínky a autobusy v zúžených hrdlech. Nejlépe červen až září; brzy ráno projedete soutěsku skoro sami.', 'loop', 240, 360, 'medium',
     '[{"lat": 46.9275, "lng": 26.3708, "label": "Start: Piatra Neamț"}, {"lat": 46.9139, "lng": 26.0906, "label": "Bicaz"}, {"lat": 46.8103, "lng": 25.8236, "label": "Cheile Bicazului"}, {"lat": 46.7886, "lng": 25.7908, "label": "Lacu Roșu"}, {"lat": 46.7220, "lng": 25.6003, "label": "Gheorgheni"}, {"lat": 46.9394, "lng": 25.7550, "label": "Tulgheș"}, {"lat": 47.0364, "lng": 25.9367, "label": "Durău"}, {"lat": 46.9275, "lng": 26.3708, "label": "Cíl: Piatra Neamț"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=46.9275,26.3708&destination=46.9275,26.3708&travelmode=driving&waypoints=46.9139,26.0906%7C46.8103,25.8236%7C46.7886,25.7908%7C46.7220,25.6003%7C46.9394,25.7550%7C47.0364,25.9367', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cheile%20Bicazului,%20(gorges%20de%20bicaz)%20(1).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cheile%20Bicazului,%20(gorges%20de%20bicaz)%20(1).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lacul%20Ro%C8%99u%20-%20lac%20de%20baraj%20natural%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ceahlau%20Toaca.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Baraj%20Bicaz%20vedere%20spre%20lacul%20Izvorul%20Muntelui.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Piatra%20Neamt%20Turnul%20lui%20Stefan%20,.jpg"}'::text[], '{"Soutěska Bicaz (Cheile Bicazului)","Rudé jezero (Lacu Roșu)","Masiv Ceahlău","Přehrada Izvorul Muntelui (Barajul Bicaz)","Piatra Neamț"}'::text[], '{"RO"}'::text[], false, 4980, 'approved');

  -- Brašov, Bran a Peleș – hrady pod Karpaty
  delete from public.routes where name = 'Brašov, Bran a Peleș – hrady pod Karpaty' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Brašov, Bran a Peleș – hrady pod Karpaty', 'Klasika mezi rumunskými okruhy: gotický Brašov s Černým kostelem, pohádkový zámek Peleș v Sinaii, selská pevnost Râșnov na skále a samozřejmě Bran, hrad spojovaný s Drákulou. Mezi nimi se jezdí pod stěnami pohoří Bucegi a Piatra Craiului, závěr obstará lesní stoupání do Poiany Brașov. Silnice jsou kvalitní, ale DN1 u Sinaie patří k nejvytíženějším v zemi — o víkendech počítejte s kolonami, hrady i silnice jsou nejpříjemnější ve všední den brzy ráno. Vhodné od jara do podzimu, na Peleș si vyhraďte aspoň dvě hodiny.', 'loop', 155, 240, 'easy',
     '[{"lat": 45.6427, "lng": 25.5887, "label": "Start: Brašov"}, {"lat": 45.3553, "lng": 25.5481, "label": "Sinaia"}, {"lat": 45.4964, "lng": 25.5750, "label": "Predeal"}, {"lat": 45.5883, "lng": 25.4606, "label": "Râșnov"}, {"lat": 45.5150, "lng": 25.3672, "label": "Bran"}, {"lat": 45.5958, "lng": 25.5556, "label": "Poiana Brașov"}, {"lat": 45.6427, "lng": 25.5887, "label": "Cíl: Brašov"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.6427,25.5887&destination=45.6427,25.5887&travelmode=driving&waypoints=45.3553,25.5481%7C45.4964,25.5750%7C45.5883,25.4606%7C45.5150,25.3672%7C45.5958,25.5556', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bran%20Castle%20TB1.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Biserica%20Neagra%20(Black%20Church),%20Brasov,%20Romania,%20Oct.%202012.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Peles-Castle-Sinaia-Romania.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Manastirea%20Sinaia.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Cetatea%20Rasnov%20si%20orasul.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Bran%20Castle%20TB1.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Piata%20Sfatului%20Brasov%20Ro.jpg"}'::text[], '{"Černý kostel (Brašov)","Zámek Peleș","Klášter Sinaia","Pevnost Râșnov","Hrad Bran","Restaurace: Sergiana (Brašov)"}'::text[], '{"RO"}'::text[], false, 4990, 'approved');

  -- Mărginimea Sibiului a Păltiniș
  delete from public.routes where name = 'Mărginimea Sibiului a Păltiniș' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Mărginimea Sibiului a Păltiniș', 'Kratší požitkářský okruh kolem Sibiu, evropského hlavního města kultury 2007: renesanční Piața Mare s domy s očima ve střechách, skanzen ASTRA v dubovém lese a pastevecké vesnice Mărginimie, kraje sedmihradských salašníků. Sportovní vložkou je hladké serpentinové stoupání do Păltiniș, nejvýše položeného horského letoviska v zemi (1440 m). Provoz mimo město minimální, asfalt na stoupání výborný — ideální odpolední trasa po příjezdu do Sibiu. Sjízdné od jara do pozdního podzimu, v Păltiniș bývá i v létě o deset stupňů chladněji.', 'loop', 130, 210, 'easy',
     '[{"lat": 45.7969, "lng": 24.1519, "label": "Start: Sibiu"}, {"lat": 45.7083, "lng": 24.1236, "label": "Cisnădioara"}, {"lat": 45.7000, "lng": 24.0630, "label": "Rășinari"}, {"lat": 45.6636, "lng": 23.9260, "label": "Păltiniș"}, {"lat": 45.7553, "lng": 23.9422, "label": "Sibiel"}, {"lat": 45.7644, "lng": 24.1447, "label": "Muzeum ASTRA"}, {"lat": 45.7969, "lng": 24.1519, "label": "Cíl: Sibiu"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.7969,24.1519&destination=45.7969,24.1519&travelmode=driving&waypoints=45.7083,24.1236%7C45.7000,24.0630%7C45.6636,23.9260%7C45.7553,23.9422%7C45.7644,24.1447', 'https://commons.wikimedia.org/wiki/Special:FilePath/Piata%20Mare%20din%20Sibiu.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Piata%20Mare%20din%20Sibiu.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Biserica%20fortificat%C4%83%20din%20cisn%C4%83dioara.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Rasinari%2003.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Paltinis.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/ASTRA%20National%20Museum%20Complex%20,%20main%20entrance%20of%20the%20Open%20air%20museum,%20Sibiu.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sibiu,%20Turnul%20Sfatului.jpg"}'::text[], '{"Sibiu – Piața Mare","Cisnădioara – románský kostelík","Rășinari","Păltiniș (1440 m)","Skanzen ASTRA","Restaurace: Crama Sibiul Vechi (Sibiu)"}'::text[], '{"RO"}'::text[], false, 5000, 'approved');

